using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        // SIMD path: multiply 8 floats at a time with 4-way unrolling to hide latency
        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 4)
        {
            var vecs = MemoryMarshal.Cast<float, Vector256<float>>(values);
            int vecLen = vecs.Length;
            int unrolledEnd = vecLen - (vecLen % 4);

            var acc0 = Vector256<float>.One;
            var acc1 = Vector256<float>.One;
            var acc2 = Vector256<float>.One;
            var acc3 = Vector256<float>.One;

            int vi = 0;
            for (; vi < unrolledEnd; vi += 4)
            {
                acc0 *= vecs[vi];
                acc1 *= vecs[vi + 1];
                acc2 *= vecs[vi + 2];
                acc3 *= vecs[vi + 3];
            }
            for (; vi < vecLen; vi++)
                acc0 *= vecs[vi];

            acc0 = (acc0 * acc1) * (acc2 * acc3);

            float product = acc0[0] * acc0[1] * acc0[2] * acc0[3]
                           * acc0[4] * acc0[5] * acc0[6] * acc0[7];

            i = vecLen * Vector256<float>.Count;
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4-way unrolling
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int end = values.Length - (values.Length % 4);
        for (; i < end; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        for (; i < values.Length; i++)
            p0 *= values[i];

        return (p0 * p1) * (p2 * p3);
    }
}

